/// After how may task the rewards are distributed
pub const TASK_SIZE: u32 = 1000;

sol! {
    struct TaskData {
        uint256 task_size;
        address[] performers;
    }
}

#[derive(Clone)]
pub struct Pinata {
    pub api_key: String,
    pub secret_api_key: String,
}
impl Pinata {
    pub fn api(&self) -> PinataApi { PinataApi::new(&self.api_key, &self.secret_api_key).unwrap() }
    pub async fn check_working(&self) -> Result<(), Error> {
        match self.api().pin_json(PinByJson::new(json!({"test": "test"}))).await {
            Ok(_) => Ok(()),
            Err(_) => Err(anyhow!("Pinata API not working")),
        }
    }
}
#[derive(Debug, Clone, Serialize, Deserialize)]
/// The data sent to the Othentic AVS Web API to prove the task was performed.
/// The task proof consists of the highest signed request per task per user, to
/// prove that each user has signed a request up to this height.
pub struct TaskProof {
    pub data: Vec<RequestToNetworkWithProofs>,
}
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct IPFSTaskProof {
    pub proof_of_task: IPFSHash,
}
impl IPFSTaskProof {
    pub async fn post_to_othentic_nodes(&self, othentic_rpc_url: String, private_key: String, performers: Vec<Address>) -> Result<(), Error> {
        // Convert Vec<ethers::types::Address> (H160) to Vec<alloy::alloy_primitives::Address>
        let performers: Vec<alloy::primitives::Address> = performers.into_iter().map(|a| alloy::primitives::Address::from_slice(a.as_bytes())).collect();
        let task_data = TaskData {
            task_size: U256::from(TASK_SIZE),
            performers: performers,
        };
        let result = Bytes::from(task_data.abi_encode());

        let task_definition_id = 1;

        let decoded_key = hex::decode(&private_key).unwrap();
        let signing_key = SigningKey::from_bytes(GenericArray::from_slice(&decoded_key)).unwrap();
        let signer = PrivateKeySigner::from_signing_key(signing_key);

        let performer_address = signer.address();

        info!("Address {:?}, {:?}, {:?}, {}", self.proof_of_task, result, performer_address, task_definition_id);
        let my_values = (self.proof_of_task.to_string(), &result, performer_address, task_definition_id);

        let encoded_data = my_values.abi_encode_params();

        info!("encoded_data {:?} ", encoded_data);
        let message_hash = keccak256(&encoded_data);
        info!("message_hash {} ", message_hash);

        let signature = signer.sign_hash(&message_hash).await?;
        let signature_bytes = signature.as_bytes();
        let serialized_signature = format!("0x{}", encode(signature_bytes));
        info!("Signature  {} ", serialized_signature);
        let params = vec![
            json!(self.proof_of_task),
            json!(result),
            json!(task_definition_id),
            json!(performer_address.to_checksum(None)),
            json!(serialized_signature),
        ];
        let body = json!({
            "jsonrpc": "2.0",
            "method": "sendTask",
            "params": params,
            "id": 1
        });

        info!("Body {:?}", body);
        surf::post(othentic_rpc_url)
            .body_json(&body)
            .unwrap()
            .send()
            .await
            .map_err(|e| anyhow!(format!("request to RPC failed: {}", e.to_string())))?;
        Ok(())
    }
}
type IPFSHash = String;
impl TaskProof {
    /// Pins it on IPFS and returns the ipfs hash
    pub async fn pin_ipfs(self, api: &PinataApi) -> Result<IPFSTaskProof, Error> {
        Ok(IPFSTaskProof {
            proof_of_task: api.pin_json(PinByJson::new(self)).await.map_err(|_| anyhow!("Failed to pin proof of task"))?.ipfs_hash,
        })
    }
    /// Verifies that the task proof is valid. Will error if any of the requests are invalid or if there are less than TASK_SIZE requests
    pub async fn verify(&self) -> Result<(), Error> {
        for request in self.data.iter() {
            match request.base.method.as_str() {
                "OPRFSecp256k1" | "JWTPRFSecp256k1" => {
                    verify_proofs::<32, Secp256k1>(request.proofs.clone())?;
                }
                "OPRFBabyJubJub" | "DecryptBabyJubJub" => {
                    verify_proofs::<32, BabyJubJub>(request.proofs.clone())?;
                }
                _ => bail!("Invalid method"),
            }
        }
        Ok(())
    }
}
fn verify_proofs<const N: usize, C: Curve<N>>(proofs: Vec<(String, String, String, String)>) -> Result<(), Error> {
    for proof in proofs.iter() {
        let (dleq_proof_hex, pub_key_share_hex, masked_point_hex, _) = proof.clone();

        let proof_bytes = hex::decode(dleq_proof_hex).map_err(|_| anyhow!("Failed to decode DLEQ proof"))?;
        let deserialized_proof: Box<DLEQProof<N, C>> = serde_json::from_slice(&proof_bytes).map_err(|_| anyhow!("Failed to deserialize DLEQ proof"))?;

        let pub_key_share_bytes = hex::decode(pub_key_share_hex).map_err(|_| anyhow!("Failed to decode pub key share"))?;
        let pub_key_share = C::Point::from_encoded(&pub_key_share_bytes).map_err(|_| anyhow!("Failed to decode pub key share point"))?;

        let masked_point_bytes = hex::decode(masked_point_hex).map_err(|_| anyhow!("Failed to decode masked point"))?;
        let masked_point = C::Point::from_encoded(&masked_point_bytes).map_err(|_| anyhow!("Failed to decode masked point"))?;
        deserialized_proof.verify_and_get_output(&pub_key_share, &masked_point)?;
    }
    Ok(())
}
#[derive(Serialize, Deserialize)]
/// The verifier's response to a TaskProof
pub struct VerifierResponse {
    // /// The number of requests that were verified
    // verified_requests: u128,
    pub data: IPFSTaskProof,
}

