    #[tokio::test]
    async fn test_verify_proof_from_json() -> Result<(), Box<dyn std::error::Error>> {
        // Deserialize the JSON into TaskProof (only once)
        let task_proof: TaskProof = serde_json::from_str(TASK_PROOF_JSON)?;
        println!("Task Proof: {:?}", task_proof);

        // Iterate over each RequestToNetworkWithProofs in TaskProof.data
        for (index, request) in task_proof.data.iter().enumerate() {
            println!("Verifying request #{}: {:?}", index, request);

            match request.base.method.as_str() {
                "OPRFSecp256k1" | "JWTPRFSecp256k1" => {
                    verify_proofs::<32, Secp256k1>(request.proofs.clone())?;
                }
                "OPRFBabyJubJub" | "DecryptBabyJubJub" => {
                    assert!(verify_proofs::<32, BabyJubJub>(request.proofs.clone()).is_ok());
                }
                method => {
                    return Err(format!("Invalid method: {}", method).into());
                }
            }
        }

        println!("Task Proof: {:?}", task_proof);
        Ok(())
    }
